<template><BtgPageContainer as="section" width="reading" aria-labelledby="translation-list-title"><RouterLink to="/authoring">Back to Authoring</RouterLink><div v-if="state==='loading'" role="status"><h1 id="translation-list-title">Loading translations</h1></div><div v-else-if="state==='error'" role="alert"><h1 id="translation-list-title">Translations unavailable</h1><p>We could not load translations for this source version.</p><BtgButton @click="load">Try again</BtgButton></div><template v-else><h1 id="translation-list-title">Translations</h1><p>Translations of source version <strong>{{ version }}</strong>. Each workspace remains linked to this exact version.</p><form class="translation-create" @submit.prevent="create"><BtgFormField label="Target language" description="Use a language tag such as es or pl." v-slot="{controlId,describedBy}"><BtgTextInput :id="controlId" v-model="language" required :aria-describedby="describedBy" /></BtgFormField><p v-if="message" role="status">{{ message }}</p><BtgButton type="submit" :disabled="creating">{{ creating?'Creating…':'Create translation' }}</BtgButton></form><p v-if="items.length===0" role="status">No translations have been created for this source version.</p><ol v-else class="translation-list"><li v-for="item in items" :key="item.translationId"><article><h2>{{ item.targetLanguage }}</h2><p>{{ item.completeness.translatedFields }} of {{ item.completeness.totalTranslatableFields }} fields translated · {{ item.lifecycle }}</p><RouterLink :to="`/authoring/translations/${item.translationId}`">Open {{ item.targetLanguage }} translation</RouterLink></article></li></ol></template></BtgPageContainer></template>
<script setup lang="ts">import{onBeforeUnmount,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{APIProblemError}from'../api/client';import BtgButton from'../components/BtgButton.vue';import BtgFormField from'../components/BtgFormField.vue';import BtgPageContainer from'../components/BtgPageContainer.vue';import BtgTextInput from'../components/BtgTextInput.vue';import{createTranslation,listTranslations,type TranslationSummary}from'../translations/translations';const route=useRoute(),router=useRouter(),courseId=String(route.params.courseId||''),version=String(route.params.version||''),items=ref<TranslationSummary[]>([]),state=ref<'loading'|'ready'|'error'>('loading'),language=ref(''),message=ref(''),creating=ref(false);let generation=0,active=true;watch(()=>[route.params.courseId,route.params.version],load,{immediate:true});onBeforeUnmount(()=>active=false);async function load(){const n=++generation;state.value='loading';try{const result=await listTranslations(String(route.params.courseId||''),String(route.params.version||''));if(!active||n!==generation)return;items.value=result.translations;state.value='ready'}catch{if(active&&n===generation)state.value='error'}}async function create(){if(!language.value.trim()||creating.value)return;creating.value=true;message.value='';try{const item=await createTranslation(courseId,version,language.value.trim());if(!active)return;await router.push(`/authoring/translations/${item.translationId}`)}catch(error){message.value=error instanceof APIProblemError&&error.problem&&'code'in error.problem&&error.problem.code==='translation_already_exists'?'A translation for that language already exists. Reload the list to open it.':'We could not create this translation. Your language choice is still here.'}finally{if(active)creating.value=false}}</script>
